from fractions import Fraction
from typing import Tuple


def harmonic(n: int) -> Fraction:
    """Exact H_n = 1 + 1/2 + ... + 1/n, with H_0 = 0.  O(n)."""
    total = Fraction(0)
    for k in range(1, n + 1):
        total += Fraction(1, k)
    return total


def dyadic_bracket(m: int) -> Tuple[Fraction, Fraction]:
    """The classical bracket 1 + m/2 <= H_{2^m} <= 1 + m.  O(1)."""
    return Fraction(2 + m, 2), Fraction(1 + m)


def harmonic_fade(rho0: Fraction, c: Fraction, n: int) -> Fraction:
    """Ladder with decrements d_k = c/(k+1): value rho_0 - c H_n after n steps."""
    return rho0 - c * harmonic(n)


def extinction_exponent(rho0: Fraction, c: Fraction) -> int:
    """
    Least m with c(1 + m/2) >= rho_0, so the harmonic fade is provably
    extinguished by step 2**m.  Uses only the dyadic lower bound, so it needs
    no summation: O(rho_0/c) trivial iterations, each O(1).
    """
    m = 0
    while dyadic_bracket(m)[0] * c < rho0:
        m += 1
    return m


def survival_horizon(rho0: Fraction, c: Fraction, threshold: Fraction, m: int) -> bool:
    """
    Certify, via the dyadic upper bound H_n <= H_{2^m} <= 1 + m, that the fade
    stays above `threshold` for its first 2**m steps.  O(1).
    """
    return rho0 - c * dyadic_bracket(m)[1] > threshold
